using System;
using System.Data;
using System.Collections;
using System.Windows.Forms;
using System.Text;
using DevExpress.XtraPrinting.BarCode;
using System.Drawing;

// 自定义调整字体大小的方法
public Font AdjustFontSize(string text, float containerWidth, Font originalFont)
{
    using (Graphics g = Graphics.FromImage(new Bitmap(1, 1))) // 创建Graphics对象
    {
        SizeF textSize = g.MeasureString(text,originalFont); // 测量文本大小
        float scale =containerWidth/textSize.Width; // 计算缩放比例
        
        // 如果缩放比例小于1，说明需要缩小字体
        if (scale <1)
        {
            // 按比例缩小字体，并确保不小于最小字体大小（如8pt）
            float newSize = Math.Max(originalFont.Size*scale,1);
            return new Font(originalFont.FontFamily, newSize, originalFont.Style);
        }
        
        // 如果不需要缩小，则返回原始字体
        return originalFont;
    }
}

