using System;
using System.Data;
using System.Collections;
using System.Windows.Forms;
using System.Text;
using DevExpress.XtraPrinting.BarCode;


public static string Trim(object obj)
{
   if ( obj == null || obj == DBNull.Value )
      return "";
   else
      return obj.ToString().Trim();
}
public static double Val(object obj)
{
   if ( obj == null || obj == DBNull.Value || obj.ToString() == "" )
       return 0;
   else
       {
          double returnValue = 0;
          double.TryParse(obj.ToString(), out returnValue);
          return returnValue;
        }
}

private void Detail_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {

  string sp ="";
  string sp1 ="";
  DataSet dsMain = XRMainReport.DataSource as DataSet; 
  DataTable dtJobAssign = dsMain.Tables["JobAssign"];
  DataTable dtJobGrayRecord = dsMain.Tables["JobGrayRecord"];
  DataTable dtJobProcess = dsMain.Tables["JobProcess"];
  DataTable dtJobAtte = dsMain.Tables["JobAtte"];
  DataTable dtSheet = dsMain.Tables["JobSheet"];
  DataTable dtSheetPrint = dsMain.Tables["JobSheetPrintList"];

  double AddWeigth=Val(this.GetCurrentColumnValue("AddWeigth"));
  double TubeWeight=Val(this.GetCurrentColumnValue("TubeWeight"));
  double PreVatQty=Val(this.GetCurrentColumnValue("PreVatQty"));
  double PreRolls=Val(this.GetCurrentColumnValue("PreRolls"));
  double SumAssignedWeightQty=Val(this.GetCurrentColumnValue("SumAssignedWeightQty"));
  double SumAssignedRolls=Val(this.GetCurrentColumnValue("SumAssignedRolls"));
  double SumAssignedLengthQty=Val(this.GetCurrentColumnValue("SumAssignedLengthQty"));
  double AssignUnit=Val(this.GetCurrentColumnValue("AssignUnit"));

    if(AssignUnit==1)//开卡单位Kg
    {
      if(SumAssignedWeightQty>0) 
 {
 label1.Text=Trim(string.Format("{0:#############0.##}",SumAssignedWeightQty));
      label3.Text=Trim(string.Format("{0:#############0.##}",SumAssignedRolls));
 }
 else
 {
 label1.Text=Trim(string.Format("{0:#############0.##}",PreVatQty));
      label3.Text=Trim(string.Format("{0:#############0.##}",PreRolls));
   }
      
    }

   else if(AssignUnit==0)//开卡单位M
    {
      if(SumAssignedLengthQty>0)
 {
 label2.Text=Trim(string.Format("{0:#############0.##}",SumAssignedLengthQty))+"M";
      label3.Text=Trim(string.Format("{0:#############0.##}",SumAssignedRolls));
 }
 else
 {
 label2.Text=Trim(string.Format("{0:#############0.##}",PreVatQty))+"M";
      label3.Text=Trim(string.Format("{0:#############0.##}",PreRolls));
   }
    }
      


/*
if (dtSheetPrint!= null && dtSheetPrint.Rows.Count > 0)
{
  string strRedoReasonID=Trim(this.GetCurrentColumnValue("RedoReasonID"));
  string strRedoDeptID_R=Trim(this.GetCurrentColumnValue("RedoDeptID_R"));
  string strSplitCardReason=Trim(this.GetCurrentColumnValue("SplitCardReason"));
   if(strRedoReasonID!="")    //   返修原因          
   {
      label3.Text="返修原因:"+strRedoReasonID+"/"+"责任部门:"+strRedoDeptID_R;
       //20230220   tableCell46.Text="返修原因:"+strRedoReasonID+"/"+"责任部门:"+strRedoDeptID_R;
   }
   if(strSplitCardReason!="")    //   返修原因          
   {
      label3.Text="拆卡原因:"+strSplitCardReason;
   }
 }
*/

//////////////////////////////////////////////////////////////////////////
////工序组合打印
 if (dtJobProcess != null && dtJobProcess.Rows.Count > 0 )
  {
    StringBuilder sb= new StringBuilder();
    foreach(DataRow dr in dtJobProcess.Rows)
    {
         
     string sAtteValue=dr["ProcessID_R"].ToString();
     sb.Append(sAtteValue+"→");
       
     
    }
 if(sb.Length>0)
  sb.Remove(sb.Length-1,1);
    tableCell34.Text="  "+Trim(sb.ToString());  
  }
///////////////////////////////////////////////////////////////////


////批号组合打印

 ///////////////////////////////////////////////////////////////////


 if (dtJobAtte!= null && dtJobAtte.Rows.Count > 0)
      {
          string str00="";
          string str01="";
          string str02="";
          string str03="";
          string str04="";

          foreach (DataRow dr in dtJobAtte.Rows)
          {
             if (Trim(dr["FieldType"])=="00")
                str00=str00+","+Trim(dr["AtteValue"])+":"+Trim(dr["Description"]);
                  //str00=str00+","+Trim(dr["AtteValue"]);

             else if(Trim(dr["FieldType"])=="01")
                  str01=str01+","+Trim(dr["AtteValue"])+":"+Trim(dr["Description"]);  
                  //str01=str01+","+Trim(dr["AtteValue"]);  
        
             else if(Trim(dr["FieldType"])=="02")
                str02=str02+","+Trim(dr["AtteValue"])+":"+Trim(dr["Description"]); 
                  //str02=str02+","+Trim(dr["AtteValue"]);
            
             else if(Trim(dr["FieldType"])=="03")
                  str03=str03+"；"+Trim(dr["AtteValue"])+Trim(dr["Description"]); 
                  //str03=str03+","+Trim(dr["AtteValue"]);
            
             else if(Trim(dr["FieldType"])=="05")
                str04=str04+","+Trim(dr["AtteValue"])+":"+Trim(dr["Description"]); 
                 // str04=str04+"-"+Trim(dr["AtteValue"]);
          }

           if(str00!="")   //另收费项目
           {
           tableCell39.Text="              "+str00.Substring(1,str00.Length-1);
           }

           if(str01!="")  //包装要求   
           {
           tableCell21.Text=str01.Substring(1,str01.Length-1);
           }

           if(str02!="")//染色要求
           {
            tableCell37.Text=" "+str02.Substring(1,str02.Length-1);
           }

           if(str03!="")//质量要求 
           {
           tableCell38.Text="  "+str03.Substring(1,str03.Length-1);
           }
                      
        }


}

