public static string Trim(object obj)
{
   if ( obj == null || obj == DBNull.Value )
      return "";
   else
      return obj.ToString().Trim();
}
public static double Val(object obj)
{
   if ( obj == null || obj == DBNull.Value || obj.ToString() == "" )
       return 0;
   else
       {
          double returnValue = 0;
          double.TryParse(obj.ToString(), out returnValue);
          return returnValue;
        }
}


private void tableCell2_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
string strRecipeUnit=Trim(this.GetCurrentColumnValue("RecipeUnit"));
string strRecipeUnit_R=Trim(this.GetCurrentColumnValue("RecipeUnit_R"));
   //MessageBox.Show(strRecipeUnit);
   if (strRecipeUnit=="0")
   {
    tableCell22.Text="%";
   }
   else if (strRecipeUnit=="1")
   {
    tableCell22.Text="g/l";
   }
   else
   {
    tableCell22.Text=strRecipeUnit_R;
   }

}

private void tableCell8_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
string strRecipeUnit=Trim(this.GetCurrentColumnValue("WeightUnit"));
string strRecipeUnit_R=Trim(this.GetCurrentColumnValue("WeightUnit_R"));
   //MessageBox.Show(strRecipeUnit);
   if (strRecipeUnit=="G")
   {
    tableCell24.Text="g";
   }
   else if (strRecipeUnit=="K")
   {
    tableCell24.Text="kg";
   }
   else
   {
    tableCell24.Text=strRecipeUnit_R;
   }

}

private void tableCell23_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
string strStuffID=Trim(this.GetCurrentColumnValue("StuffID"));
double Qty=Val(this.GetCurrentColumnValue("NeedQty"));
  if (strStuffID=="1Z001")

  {
   tableCell23.Text=Trim(string.Format("{0:#####0.##}",Qty*4));
  }
}

private void tableCell18_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
string strPhaseID=Trim(this.GetCurrentColumnValue("PhaseID_R"));
string strPhaseNo=Trim(this.GetCurrentColumnValue("PhaseNo"));
string strProgramID=Trim(this.GetCurrentColumnValue("ProgramID"));

tableCell18.Text=strProgramID+"    "+strPhaseNo+strPhaseID;
//tableCell2.Text=strProgramID;



}

private void tableCell56_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
string AutoSysIDs=Trim(this.GetCurrentColumnValue("AutoSysIDs"));
if(AutoSysIDs=="0")
  {
   tableCell56.Text="手动";
 
  }
else if(AutoSysIDs=="")
  {
   tableCell56.Text="";
 
  }
else 
  {
   tableCell56.Text="自动";
 
  }

}

