private void Detail_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {

  string sp ="";
  DataSet dsMain = XRMainReport.DataSource as DataSet; 
  DataTable dtJobAssign = dsMain.Tables["JobAssign"];
  DataTable dtJobGrayRecord = dsMain.Tables["JobGrayRecord"];
  DataTable dtJobProcess = dsMain.Tables["JobProcess"];
  DataTable dtJobAtte = dsMain.Tables["JobAtte"];
  DataTable dtSheet = dsMain.Tables["JobSheet"];
  DataTable dtSheetPrint = dsMain.Tables["JobSheetPrintList"];

  double AddWeigth=Val(this.GetCurrentColumnValue("AddWeigth"));
  double TubeWeight=Val(this.GetCurrentColumnValue("TubeWeight"));
  double PreVatQty=Val(this.GetCurrentColumnValue("PreVatQty"));
  double PreRolls=Val(this.GetCurrentColumnValue("PreRolls"));
  double SumAssignedWeightQty=Val(this.GetCurrentColumnValue("SumAssignedWeightQty"));
  double SumAssignedRolls=Val(this.GetCurrentColumnValue("SumAssignedRolls"));
  double SumAssignedLengthQty=Val(this.GetCurrentColumnValue("SumAssignedLengthQty"));
  double AssignUnit=Val(this.GetCurrentColumnValue("AssignUnit"));

      /*20230220
  if((SumAssignedWeightQty>0)&&(AssignUnit==2))//开卡单位Y
    {
      tableCell18.Text=Trim(string.Format("{0:#############0.##}",SumAssignedWeightQty))+"Y";
      tableCell44.Text=Trim(string.Format("{0:#############0.##}",SumAssignedWeightQty))+"Y";
      //tableCell82.Text=Trim(string.Format("{0:#############0.##}",SumAssignedWeightQty))+"Y";
    }
   else if((SumAssignedWeightQty>0)&&(AssignUnit==4))//开卡单位Kg
    {
      tableCell18.Text=Trim(string.Format("{0:#############0.##}",SumAssignedWeightQty))+"Kg";
      tableCell44.Text=Trim(string.Format("{0:#############0.##}",SumAssignedWeightQty))+"Kg";
      //tableCell82.Text=Trim(string.Format("{0:#############0.##}",SumAssignedWeightQty))+"Kg";
    }
   else if((SumAssignedWeightQty>0)&&(AssignUnit==1))//开卡单位Kg
    {
      tableCell18.Text=Trim(string.Format("{0:#############0.##}",SumAssignedWeightQty))+"Kg";
      tableCell44.Text=Trim(string.Format("{0:#############0.##}",SumAssignedWeightQty))+"Kg";
      //tableCell82.Text=Trim(string.Format("{0:#############0.##}",SumAssignedWeightQty))+"Kg";
    }


   else if((SumAssignedWeightQty>0)&&(AssignUnit==0))//开卡单位M
    {
      tableCell18.Text=Trim(string.Format("{0:#############0.##}",SumAssignedWeightQty))+"M";
      tableCell44.Text=Trim(string.Format("{0:#############0.##}",SumAssignedWeightQty))+"M";
      //tableCell82.Text=Trim(string.Format("{0:#############0.##}",SumAssignedWeightQty))+"M";
    }
    else if((SumAssignedWeightQty==0)&&(AssignUnit==4))//开卡单位Kg

    {
      tableCell18.Text=Trim(string.Format("{0:#############0.##}",PreVatQty))+"Kg";
      tableCell44.Text=Trim(string.Format("{0:#############0.##}",PreVatQty))+"Kg";
      //tableCell82.Text=Trim(string.Format("{0:#############0.##}",PreVatQty))+"Kg";

    }

    else if((SumAssignedWeightQty==0)&&(AssignUnit==1))//开卡单位Kg

    {
      tableCell18.Text=Trim(string.Format("{0:#############0.##}",PreVatQty))+"Kg";
      tableCell44.Text=Trim(string.Format("{0:#############0.##}",PreVatQty))+"Kg";
      //tableCell82.Text=Trim(string.Format("{0:#############0.##}",PreVatQty))+"Kg";

    }



