using System;
using System.Data;
using System.Collections;
using System.Windows.Forms;
using System.Text;


public static string Trim(object obj)
{
   if ( obj == null || obj == DBNull.Value )
      return "";
   else
      return obj.ToString().Trim();
}

public static double Val(object obj)
{
   if ( obj == null || obj == DBNull.Value || obj.ToString() == "" )
       return 0;
   else
       {
          double returnValue = 0;
          double.TryParse(obj.ToString(), out returnValue);
          return returnValue;
        }
}



private void Z06102_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
DataSet dsMain = XRMainReport.DataSource as DataSet;
  DataTable dtRecord = dsMain.Tables["ProdInRecord"];
  double RollValue=0;
  if (dtRecord != null && dtRecord.Rows.Count > 0)
  {
    string strDetailNo =dtRecord.Rows[0]["SheetSeries"].ToString(); 
    string strSheetSeries =dtRecord.Rows[0]["SheetSeries"].ToString();
    int iCnt = dtRecord.Rows.Count;
     int iTail = iCnt % 80;
     if (iTail > 0)
     {
       for (int i = 0;i < 80-iTail;i++)
       {
         DataRow drNew = dtRecord.NewRow();
         drNew["SheetSeries"] =strSheetSeries;
         drNew["SheetSeries"] =strDetailNo ;
         drNew["RollNo"] =(Val(dtRecord.Rows[iCnt-1]["RollNo"])+i+1).ToString().PadLeft(3, '0');
         drNew.EndEdit();
         dtRecord.Rows.Add(drNew);
       } 
     }
   }
}

