private void Detail_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
      string sp ="";
      DataSet dsMain = XRMainReport.DataSource as DataSet;
      DataTable dtRecord = dsMain.Tables["JobAtte"];
      DataTable dtSheet=dsMain.Tables["JobSheet"];
      DataTable dtJobAssign= dsMain.Tables["JobAssign"];
      DataTable dtJobProcess = dsMain.Tables["JobProcess"];
     if (dtJobProcess != null && dtJobProcess.Rows.Count > 0)
      {
          string strProcessID="";


          foreach (DataRow dr in dtJobProcess.Rows)
          {
             if (Trim(dr["ProcessID"])=="GX03")
             strProcessID="定胚";  
         }
           if(strProcessID!="")   //是否定胚
           {
            //tableCell34.Text=strProcessID.Substring(1,strProcessID.Length-1);
            tableCell34.Text=strProcessID;
           }
       
        }

////////////////////////////////////////////////////////////////////////////////////

     if (dtRecord != null && dtRecord.Rows.Count > 0)
      {
          string str01="";
          string str02="";
          string str03="";
          string str04="";
          string str05="";
          string str06="";
          string str07="";
          string str08="";
          double AddWeigth=Val(this.GetCurrentColumnValue("AddWeigth"));
          double TubeWeight=Val(this.GetCurrentColumnValue("TubeWeight"));
          double PreVatQty=Val(this.GetCurrentColumnValue("PreVatQty"));
          double PreRolls=Val(this.GetCurrentColumnValue("PreRolls"));

          foreach (DataRow dr in dtRecord.Rows)
          {
             if (Trim(dr["FieldType"])=="01")
                //str01=str01+","+Trim(dr["AtteValue"])+":"+Trim(dr["Description"]);
                  str01=str01+","+Trim(dr["Description"]);
             else if(Trim(dr["FieldType"])=="02")
                //str02=str02+","+Trim(dr["AtteValue"])+":"+Trim(dr["Description"]);  
                  str02=str02+","+Trim(dr["Description"]);          
             else if(Trim(dr["FieldType"])=="03")
                //str03=str03+","+Trim(dr["AtteValue"])+":"+Trim(dr["Description"]); 
                  str03=str03+","+Trim(dr["Description"]);            
             else if(Trim(dr["FieldType"])=="04")
                //str04=str04+","+Trim(dr["AtteValue"])+":"+Trim(dr["Description"]); 
                  str04=str04+","+Trim(dr["Description"]);            
             else if(Trim(dr["FieldType"])=="05")
                //str05=str05+","+Trim(dr["AtteValue"])+":"+Trim(dr["Description"]); 
                  str05=str05+"-"+Trim(dr["AtteValue"]); 
             else if(Trim(dr["FieldType"])=="06")
               // str06=str06+","+Trim(dr["AtteValue"])+":"+Trim(dr["Description"]);
                  str06=str06+","+Trim(dr["Description"]);   
         }
////////////////////////////////////////////////////////////////////////////////////
           if(str01!="")   //配布要求
           {
            tableCell68.Text=str01.Substring(1,str01.Length-1);
           }
           if(str02!="")  //染色要求     
          {
            tableCell75.Text=str02.Substring(1,str02.Length-1);
            tableCell36.Text=str02.Substring(1,str02.Length-1);
            tableCell15.Text=str02.Substring(1,str02.Length-1);


           }

           if(str03!="")//定型要求  
           {
            tableCell176.Text=str03.Substring(1,str03.Length-1);
           }
           if(str04!="")//质量要求 
           {
           tableCell177.Text=str04.Substring(1,str04.Length-1);
           }
           if(str05!="")//另收费项目
           {
           tableCell78.Text=str05.Substring(1,str05.Length-1);
           }
           if(str06!="")//包装要求
           { 
              if((TubeWeight>0)&&(AddWeigth>0))
              {         
                 tableCell178.Text=str06.Substring(1,str06.Length-1)+"纸筒："+Trim(TubeWeight)+"kg；"+"成品加重："+Trim(AddWeigth)+"kg；"; 
              }  
               if((TubeWeight==0)&&(AddWeigth==0))
              {
                 tableCell178.Text=str06.Substring(1,str06.Length-1);
              }
              if((TubeWeight>0)&&(AddWeigth==0))
              {
                 tableCell178.Text=str06.Substring(1,str06.Length-1)+"纸筒："+Trim(TubeWeight)+"kg；";
              }
              if((TubeWeight==0)&&(AddWeigth>0))
              {
                 tableCell178.Text=str06.Substring(1,str06.Length-1)+"成品加重："+Trim(AddWeigth)+"kg；";
              }


           }
         tableCell16.Text=Trim(PreRolls)+"条"+Trim(PreVatQty)+"kg";
        }

/////////////////////////////////////////////////////////////////////////////////////////
////////////// 配布仓位
  if (dtJobAssign != null && dtJobAssign.Rows.Count > 0 )
  {
    StringBuilder sb= new StringBuilder();
    foreach(DataRow dr in dtJobAssign.Rows)
    {
         
     string sAtteValue=dr["StorageUnitID_R"].ToString();
     sp +=sAtteValue+"/";
     sb.Append(sAtteValue+"/");
      
     
    }
 if(sb.Length>0)
  sb.Remove(sb.Length-1,1);
    tableCell26.Text=Trim(sb.ToString());
  }

///////////////////////////////////////////////////////////////////////////////////////// 


}


