private void Z06102_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
DataSet dsMain = XRMainReport.DataSource as DataSet;
  DataTable dtRecord = dsMain.Tables["ProdOutRecord"];
  double RollValue=0;
  if (dtRecord != null && dtRecord.Rows.Count > 0)
  {
    foreach(DataRow dr in dtRecord.Rows)
   {
        if(Val(dr["WeightQty"])>0 || Val(dr["LengthQty"])>0)
           RollValue=RollValue+1;
    }
    string strDetailNo =dtRecord.Rows[0]["DetailNo"].ToString(); 
    string strSheetSeries =dtRecord.Rows[0]["SheetSeries"].ToString();
    int iCnt = dtRecord.Rows.Count;
     int iTail = iCnt % 52;
     if (iTail > 0)
     {
       for (int i = 0;i < 52-iTail;i++)
       {
         DataRow drNew = dtRecord.NewRow();
         drNew["SheetSeries"] =strSheetSeries;
         drNew["DetailNo"] =strDetailNo ;
         //drNew["RollNo"] = (iCnt + i + 1).ToString().PadLeft(3, '0');
         drNew["RollNo"] =(Val(dtRecord.Rows[iCnt-1]["RollNo"])+i+1).ToString().PadLeft(3, '0');

         drNew.EndEdit();
         dtRecord.Rows.Add(drNew);
       } 
     }
   }
 //label6.Text=Trim(dtRecord.Rows.Count);
}

