 private void Detail_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) 
{
 DataSet dsMain = XRMainReport.DataSource as DataSet;
 DataTable dtRecordout = dsMain.Tables["ProdOut"];
 DataTable dtRecordoutDetail = dsMain.Tables["ProdOutDetail"];
 DataTable dtProdoutPrintNo = dsMain.Tables["ProdOutPrintNo"];
  //MessageBox.Show(dtRecordoutDetail.Rows.Count.ToString());
  if (dtRecordoutDetail != null && dtRecordoutDetail.Rows.Count > 0)
  {    
  string strSheetSeries =Trim(this.GetCurrentColumnValue("SheetSeries"));
  string strDetailNo =Trim(this.GetCurrentColumnValue("DetailNo")); 
  //MessageBox.Show(Trim(strDetailNo));
  DataRow[] drlFilterNo = dtProdoutPrintNo.Select("DetailNo='"+strDetailNo+"'");
  label15.Text=Trim(drlFilterNo[0]["OutNo"]);
  TF.ReportDesign.RpControl.XRSubReport RpSub = ((DevExpress.XtraReports.UI.XRSubreport)R00041).ReportSource as TF.ReportDesign.RpControl.XRSubReport;
  DataSet dsRp = RpSub.DataSource as DataSet;
  string strMember = RpSub.DataMember;
  DataRow[] drlFilter = dsMain.Tables["ProdOutRecord"].Select("DetailNo='"+strDetailNo+"'");
  DataSet dsNew = new DataSet();
  dsNew.Merge(drlFilter);

  
  if (dsNew!= null && dsNew.Tables[0].Rows.Count > 0)
  {
     int iCnt = dsNew.Tables[0].Rows.Count;
     int iTail = iCnt % 70;   
     if (iTail > 0)
     {
       for (int i = 0;i < 70-iTail;i++)
       {
         DataRow drNew = dsNew.Tables[0].NewRow();
         drNew["SheetSeries"] =strSheetSeries;
         drNew["DetailNo"] =strDetailNo ;
         drNew["RollNo"] =(Val(dsNew.Tables[0].Rows[iCnt-1]["RollNo"])+i+1).ToString().PadLeft(3, '0');
         drNew.EndEdit();
         dsNew.Tables[0].Rows.Add(drNew);
       } 
     }
   }
   if (dsNew.Tables.Count > 0)
   {     
     RpSub.DataMember = dsNew.Tables[0].TableName;     
   }
   else
   {
     RpSub.DataMember ="";
   }
   RpSub.DataSource = dsNew;
  
 /*TF.ReportDesign.RpControl.XRSubReport RpSub1 = ((DevExpress.XtraReports.UI.XRSubreport)R00042).ReportSource as TF.ReportDesign.RpControl.XRSubReport;
  DataSet dsRp1 = RpSub1.DataSource as DataSet;
  string strMember1 = RpSub1.DataMember;
  DataRow[] drlFilter1 = dsMain.Tables["ProdOutPrintList22"].Select("DetailNo='"+strDetailNo+"'");
  DataSet dsNew1 = new DataSet();
  dsNew1.Merge(drlFilter1);
  if (dsNew1.Tables.Count > 0)
   {     
     RpSub1.DataMember = dsNew1.Tables[0].TableName;     
   }
   else
   {
     RpSub1.DataMember ="";
   }

   RpSub1.DataSource = dsNew1; */
  }
}

