public static string Trim(object obj)
{
   if ( obj == null || obj == DBNull.Value )
      return "";
   else
      return obj.ToString().Trim();
}

private void DetailReport_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
      DataSet dsMain = XRMainReport.DataSource as DataSet;
      DataTable dtRecord = dsMain.Tables["FixedPriceDetail"];
      if (dtRecord != null && dtRecord.Rows.Count > 0 && dtRecord.Rows.Count<14)
   {
         for (int i=dtRecord.Rows.Count+1;i<=12;i++)
         {
              DataRow drNew = dtRecord.NewRow();
              drNew["DetailNo"] =Trim(i);
              drNew.EndEdit();
              dtRecord.Rows.Add(drNew);
         }
      }

}

